begin;
do $$
declare lead uuid:=gen_random_uuid(); volunteer uuid:=gen_random_uuid(); lead_session uuid:=gen_random_uuid(); volunteer_session uuid:=gen_random_uuid(); observation uuid:=gen_random_uuid(); rejected boolean; test_county text; test_species text; item jsonb;
begin
 select id into test_county from public.isitusa_catalog where kind='county' limit 1;
 select id into test_species from public.isitusa_catalog where kind='species' limit 1;
 insert into auth.users(id,email) values(lead,lead::text||'@example.invalid'),(volunteer,volunteer::text||'@example.invalid');
 insert into auth.sessions(id,user_id) values(lead_session,lead),(volunteer_session,volunteer);
 insert into public.isitusa_staff(user_id,email,display_name,permissions) values(lead,lead::text||'@example.invalid','Synthetic lead',array['review','review_decide']),(volunteer,volunteer::text||'@example.invalid','Synthetic reviewer',array['review']);
 perform public.isitusa_submit_sighting(observation,jsonb_build_object('species_label','PRIVATE LABEL','county_id',test_county,'observed_on','2026-01-01','location_note','PRIVATE LOCATION','latitude',40,'longitude',-80,'notes','PRIVATE NOTES','contact_email','private@example.invalid','permission_version','test','authority_sharing',false),'[]');
 if exists(select 1 from public.isitusa_public_observations(observation)) then raise exception 'FAIL: unreviewed record public'; end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',lead,'role','authenticated','aal','aal1','session_id',lead_session)::text,true);
 set local role authenticated;
 if exists(select 1 from public.isitusa_sightings where id=observation) then raise exception 'FAIL: AAL1 read'; end if;
 rejected:=false;begin perform public.isitusa_publish_observation(observation,0,'A public summary with no private details.',true);exception when insufficient_privilege then rejected:=true;end;if not rejected then raise exception 'FAIL: AAL1 publish';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',volunteer,'role','authenticated','aal','aal2','session_id',volunteer_session)::text,true);
 rejected:=false;begin perform public.isitusa_publish_observation(observation,0,'A public summary with no private details.',true);exception when insufficient_privilege then rejected:=true;end;if not rejected then raise exception 'FAIL: volunteer publish';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',lead,'role','authenticated','aal','aal2','session_id',lead_session)::text,true);
 rejected:=false;begin perform public.isitusa_publish_observation(observation,0,'A public summary with no private details.',true);exception when raise_exception then rejected:=true;end;if not rejected then raise exception 'FAIL: submitted publication';end if;
 perform public.isitusa_review_identification(observation,0,'accepted','Synthetic identification accepted.',test_species);
 perform public.isitusa_publish_observation(observation,1,'A public summary with no private details.',true);
 select to_jsonb(p) into item from public.isitusa_public_observations(observation) p;
 if item is null or item::text like '%PRIVATE%' or item ? 'contact_email' or item ? 'latitude' or item ? 'location_note' then raise exception 'FAIL: public projection leak or missing';end if;
 rejected:=false;begin perform public.isitusa_publish_observation(observation,0,'A stale public summary with no private details.',true);exception when serialization_failure then rejected:=true;end;if not rejected then raise exception 'FAIL: stale publish';end if;
 rejected:=false;begin perform public.isitusa_save_sighting_referral(observation,1,'Test authority','https://example.invalid/report','https://example.invalid/instructions','Fixture only; appropriate taxon and jurisdiction.',false,'');exception when raise_exception then rejected:=true;end;if not rejected then raise exception 'FAIL: missing referral consent';end if;
 reset role;
 update public.isitusa_sightings set authority_sharing=true where id=observation;
 set local role authenticated;
 perform public.isitusa_save_sighting_referral(observation,1,'Test authority','https://example.invalid/report','https://example.invalid/instructions','Fixture only; appropriate taxon and jurisdiction.',false,'');
 rejected:=false;begin perform public.isitusa_save_sighting_referral(observation,1,'Test authority','https://example.invalid/report','https://example.invalid/instructions','Fixture only; appropriate taxon and jurisdiction.',true,'');exception when check_violation then rejected:=true;end;if not rejected then raise exception 'FAIL: submitted without receipt';end if;
 perform public.isitusa_review_identification(observation,1,'in_review','Reopening synthetic record.',test_species);
 if exists(select 1 from public.isitusa_public_observations(observation)) then raise exception 'FAIL: reopened record stays public';end if;
 reset role;
 update public.isitusa_staff set active=false where user_id=lead;
 set local role authenticated;
 if exists(select 1 from public.isitusa_sighting_referrals where sighting_id=observation) then raise exception 'FAIL: revoked access';end if;
 reset role;
 set local role anon;
 rejected:=false;begin perform 1 from public.isitusa_sightings where id=observation;exception when insufficient_privilege then rejected:=true;end;if not rejected then raise exception 'FAIL: anonymous private table';end if;
 reset role;
end $$;
rollback;
select 'Passed: private intake, AAL2, lead-only publication, stale versions, private projection, sharing consent, referral receipts, retraction and revocation; fixtures rolled back.' as verification;
